// ================= 15억 경계 주담대 상한 (budgetCapHtml) =================
const CAP_TAIL = " 실제로 빌릴 수 있는 돈은 LTV와 소득(DSR)에 따라 이보다 적을 수 있습니다. (금융위원회 원문 기준, 2026-10-01 확인)";
const CAP_14 = "이 예산대 바로 위 15억을 넘기면 주택담보대출 상한이 6억에서 4억으로 내려갑니다(시가 15억 이하 6억, 25억 이하 4억, 그 위 2억 — 서울 전역이 규제지역이라 누구에게나 같은 천장).";
const CAP_15 = "15억을 넘긴 집은 주택담보대출 상한이 4억입니다. 15억 이하이면 6억입니다(25억을 넘으면 2억 — 서울 전역이 규제지역이라 누구에게나 같은 천장).";
const CAP_HIGH = "이 예산대 집의 주택담보대출 상한은 4억입니다. 소득(DSR)에 따라 이보다 적을 수 있습니다.";
const CLUSTER = (since, times) => ` 대책 뒤(${since}~) 거래를 세면 15억 바로 아래에 몰린 정도가 이웃 경계(14억·16억)의 ${times}배입니다 — 억 단위 어림수에 몰리는 몫을 빼고도 남는 몫입니다.`;
const STATS = { since: "2025-10-16", deals: 5000, times: 1.8 };
const CAPP = (sentence, link = "") => P("budget-loan budget-cap", sentence, link);
BAD_BANDS.forEach(([cond, value], i) => {
  add(`CP-E${String(i + 1).padStart(2, "0")}`, CP, `예산대 없음(${cond}) → 빈 문자열`, [value, STATS], "", { empty: "" });
});
add("CP-14a", CP, "14억대, 몰림 통계 있음 → 상한 하락 문장 + 몰림 문장(링크 없음: 문장이 장에 그대로 있다)", [band(14), STATS], CAPP(CAP_14 + CLUSTER("2025-10-16", 1.8) + CAP_TAIL));
add("CP-14b", CP, "14억대, 통계 null → 몰림 문장 없음(표본 문턱은 빌더 clustering이 정한다)", [band(14), null], CAPP(CAP_14 + CAP_TAIL));
add("CP-14c", CP, "14억대, 통계 undefined(인자 없음)", [band(14)], CAPP(CAP_14 + CAP_TAIL));
add("CP-15a", CP, "15억대, 통계 있음 → 15억 넘긴 집 문장 + 몰림 문장", [band(15), STATS], CAPP(CAP_15 + CLUSTER("2025-10-16", 1.8) + CAP_TAIL));
add("CP-15b", CP, "15억대, 통계 null", [band(15), null], CAPP(CAP_15 + CAP_TAIL));
for (const [cond, stats] of [["0", 0], ["빈 문자열", ""], ["false", false]]) {
  add(`CP-14f-${cond}`, CP, `14억대, 통계가 거짓(${cond}) → 몰림 문장 없음`, [band(14), stats], CAPP(CAP_14 + CAP_TAIL));
}
// 통계가 참이면(무엇이든) 몰림 문장이 있고, 값은 글자 그대로 문장에 들어간다 - 값이 없으면 "undefined"가 된다(예전 그대로)
for (const [i, [cond, stats, since, times]] of [
  ["빈 객체", {}, "undefined", "undefined"],
  ["빈 배열", [], "undefined", "undefined"],
  ["since 없음·times 있음", { times: 2.5 }, "undefined", "2.5"],
  ["since만 있고 times 없음", { since: "2026-01-01" }, "2026-01-01", "undefined"],
  ["since null", { since: null, times: 3 }, "null", "3"],
  ["since false", { since: false, times: 3 }, "false", "3"],
  ["since 0", { since: 0, times: 0 }, "0", "0"],
  ["since 빈 문자열", { since: "", times: "" }, "", ""],
  ["since {}", { since: {}, times: {} }, "[object Object]", "[object Object]"],
  ["since [1,2]", { since: [1, 2], times: [3, 4] }, "1,2", "3,4"],
  ["since NaN·times Infinity", { since: NaN, times: Infinity }, "NaN", "Infinity"],
  ["since true", { since: true, times: true }, "true", "true"],
  ["since 특수문자(이스케이프된다)", { since: SP, times: SP }, SP_OUT, SP_OUT],
  ["이미 이스케이프된 글자(&amp; → &amp;amp;)", { since: "&amp;", times: "&#x27;" }, "&amp;amp;", "&amp;#x27;"],
  ["통계가 문자열 \"x\"(.since가 없다)", "x", "undefined", "undefined"],
  ["통계가 숫자 5", 5, "undefined", "undefined"],
  ["통계가 true", true, "undefined", "undefined"],
].entries()) {
  const n = String(i + 1).padStart(2, "0");
  add(`CP-14s${n}`, CP, `14억대, 통계가 참인 값(${cond}) → 몰림 문장에 글자로 들어간다`, [band(14), stats], CAPP(CAP_14 + CLUSTER(since, times) + CAP_TAIL));
  add(`CP-15s${n}`, CP, `15억대, 통계가 참인 값(${cond})`, [band(15), stats], CAPP(CAP_15 + CLUSTER(since, times) + CAP_TAIL));
}
// 16~24억대: 구간표·소득 단서가 method.html로 갔으므로 링크가 붙는다. 통계는 읽지 않는다.
